const colors=['#729b99','#b1765d'];
function pixelBone(p,q,width,color,highlight=true){const x=Math.round(p.x),y=Math.round(p.y),xx=Math.round(q.x),yy=Math.round(q.y);ctx.lineCap='square';ctx.lineJoin='miter';line(x,y,xx,yy,'#29332d',width+2);line(x,y,xx,yy,color,width);if(highlight)line(x-width*.25,y,xx-width*.25,yy,'#eddbb044',1);ctx.lineCap='butt';}

// Gliedmaße mit zwei gleich langen Teilen: bei voller Streckung liegt das Gelenk in der Mitte, sonst beugt es zur angegebenen Seite.
function limbJoint(root,target,length,bend){const reach=Math.hypot(target.x-root.x,target.y-root.y);return reach>=length*2-.2?{x:(root.x+target.x)/2,y:(root.y+target.y)/2}:solveJoint(root,target,length,length,bend);}
function solveJoint(root,target,l1,l2,bend){const dx=target.x-root.x,dy=target.y-root.y,d=clamp(Math.hypot(dx,dy),.01,l1+l2-.05),a=Math.atan2(dy,dx),theta=Math.acos(clamp((l1*l1+d*d-l2*l2)/(2*l1*d),-1,1));return {x:root.x+Math.cos(a+theta*bend)*l1,y:root.y+Math.sin(a+theta*bend)*l1}}

function breathing(a,t=time){const g=a.g;if(g.dead||g.bisected||g.body.head.missing)return 0;const hurt=clamp((100-M.health(g))/65,0,1),tired=clamp(Math.max(g.fatigue/100,1-(a.energy??100)/(65+g.stats.stamina*1.15)),0,1),strain=Math.max(hurt,tired,(100-g.blood)/85);return Math.sin(t*(2.5+strain*6.5)+(a.seed||0))*(.35+strain*1.6);}
function expression(a){const g=a.g;if(a.shoutTimer>0)return 'shout';if(a.blindTimer>0)return 'pain';if(g.dead)return 'dead';if(a.down)return 'unconscious';if(a.facePain>0||a.hit>0||a.fallTimer>0||g.blood<38||M.health(g)<48)return 'pain';if(a.surrendered||a.state==='retreat'||a.retreat>0)return 'fear';if(a.state==='celebrate')return 'laugh';if(a.state==='charge'||a.wind>0||a.swing>0||a.state==='attack'||a.state==='execute')return 'angry';if(a.block||a.guardTime>0||a.netTimer>0)return 'focused';if(g.fatigue>65||(a.energy??100)<22)return 'tired';return g.stats.morale>62&&M.health(g)>80?'happy':'focused'}
